-- H1.21 (build 3R): row security, the framework and the chat tables (H1 3.4).
--
-- Every tenant table gets one policy, named `tenancy`, generated by
-- `tenancy_protect`: `tenancy_allows(<its tenant column>)` for reads and
-- writes, with row security FORCEd so the tables' owner (the server's own
-- role, when it isn't a superuser) is subject too.
--
-- `tenancy_allows` reads one setting, `app.tenancy`, which the server sets
-- only with set_config(.., true) as a scoped transaction begins (H1.20, R24
-- rule 3): `m:<account>|<workspace>,..` (an account in its workspaces),
-- `w:<account>|<workspace>` (one workspace), `s:<reason>` (server-wide work)
-- or `a` (before sign-in).
--
-- OBSERVE MODE. Until `app.tenancy_strict` is 'on' (H1.63 sets it on the
-- database once every call site is scoped, R42), nothing is refused:
-- - a statement with no scope at all is allowed (the server logs the call
--   site that began it, `agent_workspace::tenancy`);
-- - a row the scope would not allow is allowed too, and noted in the
--   database's log (`tenancy_refused`) with its workspace and the scope's
--   kind, so a rehearsal can find what strict mode would break (R57).
-- With strict mode on, both are refused.
--
-- DIRECT SCOPE (R20). Conversations and what hangs off them may one day
-- belong to the direct scope, readable by their participants only. Their
-- policy carries a second branch, `tenancy_direct_allows(workspace,
-- conversation)`, false until K4 makes the direct scope (stopgap): K4 owns
-- its body and replaces only that function.

-- The account the scope names, if any.
CREATE FUNCTION tenancy_account() RETURNS UUID
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT NULLIF(
        split_part(split_part(coalesce(current_setting('app.tenancy', true), ''), ':', 2), '|', 1),
        ''
    )::UUID
$$;

-- Whether row rules refuse rather than observe.
CREATE FUNCTION tenancy_strict() RETURNS BOOLEAN
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT coalesce(current_setting('app.tenancy_strict', true), '') = 'on'
$$;

-- A row the scope doesn't allow: refused in strict mode; in observe mode
-- allowed and noted in the database's log (ids and the scope's kind only).
-- Its body names nothing outside pg_catalog: pg_dump and pg_restore run
-- with an empty search_path.
CREATE FUNCTION tenancy_refused(workspace UUID) RETURNS BOOLEAN
LANGUAGE plpgsql STABLE PARALLEL SAFE AS $$
BEGIN
    IF coalesce(current_setting('app.tenancy_strict', true), '') = 'on' THEN
        RETURN false;
    END IF;
    RAISE LOG 'tenancy: a row of workspace % outside a % scope',
        workspace, split_part(coalesce(current_setting('app.tenancy', true), ''), ':', 1);
    RETURN true;
END;
$$;

-- The row rule: whether the current scope may read or write a row of
-- `workspace`. A plain SQL expression, so the planner inlines it into each
-- policy; the one function it calls is named with this schema, since
-- pg_dump reads the tables with an empty search_path.
DO $migration$
BEGIN
    EXECUTE format($function$
        CREATE FUNCTION tenancy_allows(workspace UUID) RETURNS BOOLEAN
        LANGUAGE sql STABLE PARALLEL SAFE AS $$
            SELECT CASE split_part(coalesce(current_setting('app.tenancy', true), ''), ':', 1)
                WHEN 's' THEN true
                WHEN 'w' THEN
                    workspace = NULLIF(split_part(current_setting('app.tenancy', true), '|', 2), '')::UUID
                    OR %1$I.tenancy_refused(workspace)
                WHEN 'm' THEN
                    workspace = ANY (string_to_array(
                        NULLIF(split_part(current_setting('app.tenancy', true), '|', 2), ''), ','
                    )::UUID[])
                    OR %1$I.tenancy_refused(workspace)
                WHEN 'a' THEN %1$I.tenancy_refused(workspace)
                -- No scope: allowed while observing (the server logs the call site).
                ELSE coalesce(current_setting('app.tenancy_strict', true), '') <> 'on'
            END
        $$
    $function$, current_schema());
END;
$migration$;

-- The direct scope's branch (R20): a participant reads their DMs and
-- groups whatever workspace scope they are in. Stopgap until K4.
CREATE FUNCTION tenancy_direct_allows(workspace UUID, conversation UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT false
$$;

-- Turns row security on for `target` with its one `tenancy` policy.
-- `conversation` names the row's conversation for a table that may hold
-- direct-scope rows (an expression over the row), NULL otherwise.
CREATE FUNCTION tenancy_protect(target REGCLASS, tenant_column TEXT, conversation TEXT DEFAULT NULL)
RETURNS VOID
LANGUAGE plpgsql AS $$
DECLARE
    rule TEXT := format('tenancy_allows(%I)', tenant_column);
BEGIN
    IF conversation IS NOT NULL THEN
        rule := format('(%s OR tenancy_direct_allows(%I, %s))', rule, tenant_column, conversation);
    END IF;
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', target);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', target);
    IF EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = target AND polname = 'tenancy') THEN
        EXECUTE format('DROP POLICY tenancy ON %s', target);
    END IF;
    EXECUTE format('CREATE POLICY tenancy ON %s USING (%s) WITH CHECK (%s)', target, rule, rule);
END;
$$;

-- H1.4's tables. The ones that may hold direct-scope rows name their
-- conversation.
SELECT tenancy_protect('conversations', 'workspace_id', 'id');
SELECT tenancy_protect('conversation_entries', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('conversation_members', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('conversation_notification_levels', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('conversation_pins', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('conversation_read_states', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('messages', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('message_link_previews', 'workspace_id',
    '(SELECT parent.conversation_id FROM messages parent WHERE parent.id = message_id)');
SELECT tenancy_protect('message_mentions', 'workspace_id',
    '(SELECT parent.conversation_id FROM messages parent WHERE parent.id = message_id)');
SELECT tenancy_protect('message_reactions', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('message_revisions', 'workspace_id',
    '(SELECT parent.conversation_id FROM messages parent WHERE parent.id = message_id)');
SELECT tenancy_protect('message_work_item_references', 'workspace_id',
    '(SELECT parent.conversation_id FROM messages parent WHERE parent.id = message_id)');
SELECT tenancy_protect('reply_requests', 'workspace_id', 'conversation_id');
SELECT tenancy_protect('notifications', 'workspace_id');
SELECT tenancy_protect('notification_occurrences', 'workspace_id');
SELECT tenancy_protect('notification_project_mutes', 'workspace_id');
SELECT tenancy_protect('outbox_events', 'workspace_id');
SELECT tenancy_protect('person_questions', 'workspace_id');
SELECT tenancy_protect('project_decisions', 'workspace_id');
SELECT tenancy_protect('push_deliveries', 'workspace_id');
SELECT tenancy_protect('thing_references', 'workspace_id');
